<?php require_once __DIR__.'/../includes/bootstrap.php';require_login();if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: dashboard.php');exit;}csrf_check();$uid=(int)$_SESSION['user']['id'];$job=(int)($_POST['opportunity_id']??0);$letter=trim($_POST['cover_letter']??'');if($job<1||mb_strlen($letter)<20||mb_strlen($letter)>500){flash('Please provide a valid application statement (20–500 characters).','error');header('Location: dashboard.php#opportunities');exit;}$q=$pdo->prepare('SELECT id FROM opportunities WHERE id=? AND is_active=1');$q->execute([$job]);if(!$q->fetchColumn()){flash('This opportunity is no longer available.','error');header('Location: dashboard.php');exit;}try{$q=$pdo->prepare('INSERT INTO applications(user_id,opportunity_id,cover_letter) VALUES(?,?,?)');$q->execute([$uid,$job,$letter]);flash('Application submitted successfully.');}catch(PDOException $ex){flash('You have already applied to this opportunity.','error');}header('Location: dashboard.php');exit;
